import {readdirSync, readFileSync, statSync} from 'node:fs';
import {expect, it} from 'vitest';
import {ICON_RESOURCE_DIRECTORY, INSTALLED_ICON_FILE, MAX_ICON_BYTES} from '../../apps/desktop/src/installed-app-icon';
import {PRODUCT_ROOT_NAME} from '../../apps/desktop/src/uninstall/roots';
import {forgeConfig} from '../shared/forge-config';

// resources/icon/app.ico is generated by scripts/generate-app-icons.mjs and embedded in the executable and Setup.
it('the application icon carries one square PNG entry for every Windows icon size', () => {
  const ico = readFileSync('resources/icon/app.ico');
  expect([ico.readUInt16LE(0), ico.readUInt16LE(2)]).toEqual([0, 1]);
  const count = ico.readUInt16LE(4), sizes: number[] = [];
  for (let index = 0; index < count; index++) {
    const entry = 6 + 16 * index, length = ico.readUInt32LE(entry + 8), offset = ico.readUInt32LE(entry + 12);
    const size = ico[entry] || 256;
    expect(ico[entry + 1] || 256).toBe(size);
    expect([ico.readUInt16LE(entry + 4), ico.readUInt16LE(entry + 6)]).toEqual([1, 32]);
    expect(offset + length).toBeLessThanOrEqual(ico.length);
    const png = ico.subarray(offset, offset + length);
    expect([...png.subarray(0, 8)]).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
    expect([png.readUInt32BE(16), png.readUInt32BE(20), png[24], png[25]]).toEqual([size, size, 8, 6]);
    sizes.push(size);
  }
  expect(sizes).toEqual([16, 20, 24, 32, 40, 48, 64, 128, 256]);
});

// ET-045g (REG-017, owner decision D3): the Installed apps icon comes from this file, which Forge ships as an extra resource
// for the install and updated hooks; the executable and Setup embed the same file.
it('ships the application icon as an extra resource for the Installed apps entry, from the same tracked file', () => {
  const forge = forgeConfig('production');
  expect(forge.packagerConfig.extraResource).toContain('resources/icon');
  expect(readdirSync('resources/icon').filter(name => name.toLowerCase().endsWith('.ico'))).toEqual([INSTALLED_ICON_FILE]);
  expect(`resources/${ICON_RESOURCE_DIRECTORY}/${INSTALLED_ICON_FILE}`).toBe('resources/icon/app.ico');
  const squirrel = forge.makers.find(maker => maker.name === '@electron-forge/maker-squirrel')?.config;
  expect(`${forge.packagerConfig.icon}.ico`).toBe('resources/icon/app.ico');
  expect(squirrel?.setupIcon).toBe('resources/icon/app.ico');
  // The Squirrel id names the install root and the uninstall entry whose DisplayIcon the hooks set.
  expect(squirrel?.name).toBe(PRODUCT_ROOT_NAME);
  // iconUrl stays electron-winstaller's default: the hooks place app.ico first, so Squirrel never downloads it.
  expect(squirrel).not.toHaveProperty('iconUrl');
  expect(statSync('resources/icon/app.ico').size).toBeLessThanOrEqual(MAX_ICON_BYTES);
});
